/**
 * n8n Error Workflow payload (Settings → Error Workflow on the main JMT-S workflow).
 */
const item = $input.first().json;
const err = item.execution?.error ?? {};
const failedNode = err.node?.name ?? item.execution?.lastNodeExecuted ?? 'unknown node';
const message = err.message ?? err.description ?? 'Workflow failed';

return [{
  json: {
    failure_summary: String(failedNode) + ': ' + String(message).slice(0, 450),
    external_execution_id: String(item.execution?.id ?? ''),
    failed_workflow: item.workflow?.name ?? '',
  },
}];

const prep = $('Prepare failure capture').first().json;
const lookup = $input.first().json;
const traceId = lookup.trace_id ?? null;

return [{
  json: {
    failure_summary: prep.failure_summary,
    ...(traceId
      ? {
          aegis_policy: {
            trace_id: traceId,
            decision: 'allow_with_obligation',
            recorded: true,
          },
        }
      : {}),
    aegis_tool: 'jmts.content.publish',
  },
}];
